// دالة البحث في الموسوعة
function searchAdvancedFoods(query) {
  const q = query.trim().toLowerCase();
  if (!q || q.length < 2) return [];
  return ADVANCED_FOODS.filter(f =>
    f.name.includes(q) || f.section.includes(q) || f.cat.includes(q)
  ).slice(0, 20);
}

// دالة دمج الكل في ALL_FOODS
function getAllFoods() {
  if (typeof FOODS !== "undefined") {
    return [...FOODS, ...ADVANCED_FOODS];
  }
  return ADVANCED_FOODS;
}

if (typeof module !== "undefined") module.exports = { ADVANCED_FOODS, searchAdvancedFoods, getAllFoods };